import numpy as np
import scipy.special

# scipy.special._binom_cdf(3e18, 10e18, 0.3) as np.float32 and np.float64
try:
    result_f32 = scipy.special._binom_cdf(np.float32(3e18), np.float32(10e18), np.float32(0.3))
    probe("scipy.special._binom_cdf(3e18, 10e18, 0.3) as np.float32 and np.float64", (result_f32, scipy.special._binom_cdf(np.float64(3e18), np.float64(10e18), np.float64(0.3))))
except Exception as e:
    probe_exception("scipy.special._binom_cdf(3e18, 10e18, 0.3) as np.float32 and np.float64", e)

